script:
(function () {
  'use strict';
  // Comprehensive life insurance analysis: a year-by-year survivor cash-flow plan.
  // Year t = 0, 1, ... until the survivor reaches the "plan until" age. All amounts are entered in
  // today's dollars and rise each year with inflation (college costs with college inflation;
  // Social Security with inflation, standing in for the yearly cost-of-living adjustment).
  //   Spending: "children at home" while any listed child is under 18, then "after the children
  //     leave" until the survivor's retirement age, then "in retirement".
  //   College: cost per child for each year the child is aged 18 to 18 + years - 1.
  //   Income: survivor take-home pay before retirement; pension/other income from retirement.
  //   Social Security (entered by the user): child benefit per child while that child is under 18;
  //     parent's benefit while the youngest child is under 16 (and before the survivor's own
  //     benefit starts); the survivor's own benefit from the chosen age.
  //   Gap_t = spending_t + college_t - income_t - Social Security_t (negative = surplus).
  // Cash flows happen at the start of each year; the fund then earns the return r for the year.
  // Fund needed today = smallest F_0 that pays every gap without ever going below zero and ends
  // with the amount to leave behind L (today's dollars, inflated to the end):
  //   F_T = L (1 + inflation)^T;  F_t = max(0, Gap_t + F_(t+1) / (1 + r)).
  // Life insurance to buy = max(0, paid-at-death needs + F_0 - existing cover - savings).
  // Verified (Node, scratchpad slc5/cla.test.js): with no children, no income and a constant
  //   $40,000 spending for 30 years at 5% return / 3% inflation the fund equals the closed form
  //   40,000 x (1 - q^30) / (1 - q), q = 1.03 / 1.05 -> $920,611.02; with r = inflation it equals
  //   40,000 x 30 = $1,200,000; a forward run from F_0 never dips below zero and ends at exactly L;
  //   gaps [-1,000, +5,500] at 10% -> F_0 = $4,000 (a surplus pays a later gap), while
  //   [10,000, -50,000, 1,000] -> $10,000 (a later surplus cannot pay an earlier gap); college for
  //   a 17-year-old falls in years 2-5 at cost x 1.05^t;
  //   child/parent/survivor benefit windows switch on and off at ages 18, 16 and the chosen age.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var CHILD_IDS = ['claChild1', 'claChild2', 'claChild3', 'claChild4'];

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function plan(p) {
    var T = p.planAge - p.age, rows = [], t, k;
    for (t = 0; t < T; t++) {
      var age = p.age + t, infl = Math.pow(1 + p.inflation, t), cInfl = Math.pow(1 + p.collegeInflation, t);
      var anyHome = false, youngest = Infinity, college = 0, ss = 0;
      for (k = 0; k < p.children.length; k++) {
        var ca = p.children[k] + t;
        if (ca < 18) { anyHome = true; ss += p.ssChild * 12; }
        if (ca < youngest) youngest = ca;
        if (ca >= 18 && ca < 18 + p.collegeYears) college += p.collegeCost * cInfl;
      }
      var ownBenefit = age >= p.ssWidowAge;
      if (youngest < 16 && !ownBenefit) ss += p.ssParent * 12;
      if (ownBenefit) ss += p.ssWidow * 12;
      ss *= infl;
      var spend = (anyHome ? p.expKids : (age < p.retireAge ? p.expMid : p.expRet)) * infl;
      var income = (age < p.retireAge ? p.work : p.pension) * infl;
      rows.push({ year: t + 1, age: age, income: income, ss: ss, spend: spend, college: college,
                  gap: spend + college - income - ss });
    }
    var need = p.legacy * Math.pow(1 + p.inflation, T);
    for (t = T - 1; t >= 0; t--) need = Math.max(0, rows[t].gap + need / (1 + p.ret));
    var bal = need;
    for (t = 0; t < T; t++) { bal = (bal - rows[t].gap) * (1 + p.ret); rows[t].fund = bal; }
    return { fund: need, rows: rows };
  }

  function clearBody(id) {
    var body = el(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function update() {
    var p = { age: read('claAge'), retireAge: read('claRetire'), planAge: read('claPlanAge'),
              expKids: read('claExpKids', true), expMid: read('claExpMid', true), expRet: read('claExpRet', true),
              collegeCost: read('claCollege', true), collegeYears: read('claCollegeYears', true),
              work: read('claWork', true), pension: read('claPension', true),
              ssChild: read('claSsChild', true), ssParent: read('claSsParent', true), ssWidow: read('claSsWidow', true),
              ssWidowAge: read('claSsWidowAge'), final: read('claFinal', true), mortgage: read('claMortgage', true),
              debts: read('claDebts', true), emergency: read('claEmergency', true), insurance: read('claInsurance', true),
              savings: read('claSavings', true), ret: read('claReturn'), inflation: read('claInflation'),
              collegeInflation: read('claCollegeInf'), legacy: read('claLegacy', true), children: [] };
    var msg = '', badChild = false;
    CHILD_IDS.forEach(function (id) {
      var raw = String(el(id).value).trim();
      if (raw === '') return;
      var v = Number(raw);
      if (!isFinite(v) || v < 0 || v > 30) badChild = true; else p.children.push(Math.floor(v));
    });
    var amounts = ['expKids', 'expMid', 'expRet', 'collegeCost', 'work', 'pension', 'ssChild', 'ssParent', 'ssWidow',
                   'final', 'mortgage', 'debts', 'emergency', 'insurance', 'savings', 'legacy'];
    var all = Object.keys(p).filter(function (k) { return k !== 'children'; });
    if (all.some(function (k) { return isNaN(p[k]); })) msg = 'Fill in every field (amounts can be 0).';
    else if (amounts.some(function (k) { return p[k] < 0; })) msg = 'Amounts cannot be negative.';
    else if (badChild) msg = 'Enter each child\'s age from 0 to 30, or leave it blank.';
    else if (p.age < 18 || p.age > 100 || p.planAge <= p.age || p.planAge > 110 || p.planAge - p.age > 80)
      msg = 'The survivor\'s age must be 18 to 100 and the plan must end at a later age (up to 110, at most 80 years ahead).';
    else if (p.retireAge < 0 || p.retireAge > 110) msg = 'Enter a retirement age up to 110.';
    else if (p.ssWidowAge < 60 || p.ssWidowAge > 110) msg = 'The survivor\'s own Social Security benefit can start at 60 at the earliest.';
    else if (p.collegeYears < 0 || p.collegeYears > 10) msg = 'Enter 0 to 10 years of college.';
    else if (p.ret < -10 || p.ret > 20 || p.inflation < 0 || p.inflation > 15 || p.collegeInflation < 0 || p.collegeInflation > 15)
      msg = 'Enter a return from -10% to 20% and inflation rates from 0% to 15%.';
    var error = el('claError');
    error.hidden = msg === '';
    if (msg) { error.textContent = msg; return; }
    p.age = Math.floor(p.age); p.planAge = Math.floor(p.planAge); p.collegeYears = Math.round(p.collegeYears);
    p.ret /= 100; p.inflation /= 100; p.collegeInflation /= 100;

    var r = plan(p);
    var immediate = p.final + p.mortgage + p.debts + p.emergency;
    var need = immediate + r.fund, have = p.insurance + p.savings;
    var shortYears = 0, biggest = 0, gapSum = 0, ssSum = 0;
    r.rows.forEach(function (row) {
      if (row.gap > 0.5) { shortYears++; gapSum += row.gap; }
      if (row.gap > biggest) biggest = row.gap;
      ssSum += row.ss;
    });
    setText('claBuy', money.format(Math.max(0, need - have)));
    setText('claBuyNote', need > have ? '' : 'Your existing cover and savings already meet the need.');
    setText('claNeed', money.format(need));
    setText('claHave', money.format(have));
    setText('claFund', money.format(r.fund));
    setText('claImmediate', money.format(immediate));
    setText('claShortYears', shortYears + ' of ' + r.rows.length);
    setText('claBiggest', money.format(biggest));
    setText('claGapSum', money.format(gapSum));
    setText('claSsSum', money.format(ssSum));

    var body = clearBody('claTable');
    r.rows.forEach(function (row) {
      addRow(body, [String(row.year), String(row.age), money.format(row.income), money.format(row.ss),
                    money.format(row.spend), money.format(row.college),
                    row.gap >= 0 ? money.format(row.gap) : money.format(-row.gap) + ' surplus',
                    money.format(Math.max(0, row.fund))]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('claForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
